function decodeArbitraryLine(line){var s=line.trim();if(!s)return "Blank line: no operation.";if(s[0]==="#")return "Comment: explanatory text for the human reader; Python doesn't execute it.";if(/^from \S+ import /.test(s))return "Imports a named class or function from a package. It becomes available to subsequent lines.";if(/^import /.test(s))return "Imports a library/module. 'as' creates a shorter alias for later calls.";if(/\.fit_transform\(/.test(s))return "Fit a transformer on input data and immediately transform them. Beware of fitting on held-out samples.";if(/\.fit\(/.test(s))return "Fit/train: learn parameters from provided data. Check which input features and labels are being supplied.";if(/\.predict\(/.test(s))return "Inference: use a trained model to compute predictions from feature inputs. Check the shape and ordering.";if(/train_test_split\(/.test(s))return "Split aligned feature and target samples. Check test_size, random_state, group structure and whether time order matters.";if(/\.score\(/.test(s))return "Ask a model for its built-in evaluation score. For sklearn LinearRegression this returns R², not classification accuracy.";if(/\.coef_/.test(s))return "Inspect learned coefficient(s). In linear regression, these multiply feature values.";if(/\.intercept_/.test(s))return "Inspect the learned constant/intercept in the regression equation.";if(/\.shape/.test(s))return "Read a table/array's dimensions; for X, think (observations, features).";if(/\.head\(/.test(s))return "Show the first rows of a DataFrame to inspect its contents.";if(/read_csv\(/.test(s))return "Load comma-separated values into a pandas DataFrame.";if(/\.scatter\(/.test(s))return "Draw a scatterplot of paired values; each point represents one observation.";if(/\.plot\(/.test(s))return "Draw connected plot points. Check whether x values are in the intended order.";if(/\.isna\(/.test(s))return "Find missing/unknown entries; combining with sum() counts them.";if(/\.dropna\(/.test(s))return "Drop records with missing entries according to selected axis/criteria. Consider the loss of data.";if(/\.drop_duplicates\(/.test(s))return "Remove duplicate rows under the specified criteria.";if(/\.transform\(/.test(s))return "Apply an already-fitted transformation. Unlike fit_transform(), it should not learn new parameters.";if(/\.mean\(/.test(s))return "Calculate an average across selected values or an axis.";if(/\.reshape\(/.test(s))return "Change array dimensions without changing the underlying number of elements.";if(/^\s*print\(/.test(s))return "Display a value or object in the output; useful for debugging shapes and predictions.";if(/^\s*for /.test(s))return "Loop: repeat the indented block for every item in a sequence.";if(/^\s*if /.test(s))return "Conditional: execute the indented block only when the expression is True.";if(/^\s*def /.test(s))return "Function definition: give a reusable piece of logic a name and parameters.";if(s.indexOf("=")>-1&&s.indexOf("==")===-1){var left=s.split("=")[0].trim();return "Assignment: evaluate the expression on the right and store its result under "+left+". To understand this line, trace the right-hand object's type, shape and value."}return "First identify Python syntax (name, method, indexing, operator). Next inspect the input object and its type/shape, then determine the return value. This is a heuristic, not a full interpreter."}
