function parseCSV(src){
 if(src.charCodeAt(0)===65279)src=src.slice(1);
 var rows=[],row=[],value="",quoted=false,closedQuote=false;
 function pushField(){row.push(value);value="";closedQuote=false}
 function pushRow(){if(row.some(v=>v!==""))rows.push(row);row=[]}
 for(var i=0;i<src.length;i++){
  var c=src[i];
  if(quoted){
   if(c==='"'){if(src[i+1]==='"'){value+='"';i++}else{quoted=false;closedQuote=true}}
   else value+=c;
  }else if(c==='"'){
   if(value!==""||closedQuote)throw Error("Unexpected CSV quote");quoted=true;
  }else if(c===","||c==="\n"||c==="\r"){
   if(c==="\r"&&src[i+1]==="\n")i++;
   pushField();if(c!==",")pushRow();
  }else{
   if(closedQuote)throw Error("Characters after closing CSV quote");value+=c;
  }
 }
 if(quoted)throw Error("Unclosed quoted CSV field");
 pushField();pushRow();if(!rows.length)throw Error("Empty CSV");
 var header=rows.shift(),m=header.length;
 if(header.some(x=>!x.trim()))throw Error("Missing CSV header");
 var bad=rows.findIndex(row=>row.length!==m);
 if(bad>=0)throw Error("CSV row "+(bad+2)+" has "+rows[bad].length+" fields; expected "+m);
 return {header:header,rows:rows};
}
function tableStats(){var missing=0,duplicates=0,badFare=0,seen=new Set(),fare=V.dataHeaders.findIndex(function(x){return x.toLowerCase().trim()==="fare"});V.dataRows.forEach(function(row){var key=JSON.stringify(row);if(seen.has(key))duplicates++;seen.add(key);row.forEach(function(x){if(x===""||x.toLowerCase()==="nan")missing++});if(fare>=0&&row[fare]!==""&&Number(row[fare])<0)badFare++});return {missing:missing,duplicates:duplicates,badFare:badFare}}
